using ProjectileSimulator.Models;
using ProjectileSimulator.Physics;
using ProjectileSimulator.Services;

namespace ProjectileSimulator.Tests;

/// <summary>
/// The "observations" in these tests are SYNTHETIC: they are generated by our own engine with
/// known hidden parameters, so we can check that the optimizer recovers them. They are not
/// data from Gunny.
/// </summary>
public class ReverseEngineeringTests
{
    private readonly PhysicsEngine _engine = new();
    private readonly ReverseEngineeringService _re;
    private readonly OptimizationService _opt;

    public ReverseEngineeringTests()
    {
        _re = new ReverseEngineeringService(_engine);
        _opt = new OptimizationService(_re);
    }

    private static SimulationRequest Base() => new()
    {
        WindEnabled = true,
        WindMode = WindMode.WindAcceleration,
        DragType = DragType.None,
        Integrator = IntegratorType.SemiImplicitEuler,
        DeltaTime = 0.004,
        BarrelLength = 0.3,
        Calibration = new CalibrationParameters { LaunchHeight = 0.4 }
    };

    private List<ExperimentData> SyntheticObservations(SimulationRequest hidden, bool withTime = true)
    {
        var shots = new (double angle, double power, double wind)[]
        {
            (30, 40, 0), (45, 50, 5), (60, 70, -5), (75, 80, 10), (40, 90, -10), (55, 35, 2), (20, 60, 0), (65, 55, -3)
        };
        var list = new List<ExperimentData>();
        foreach (var (angle, power, wind) in shots)
        {
            var r = hidden.Clone();
            r.Angle = angle; r.Power = power; r.Wind = wind; r.TargetCollisionEnabled = false;
            var res = _engine.Simulate(r);
            list.Add(new ExperimentData { Angle = angle, Power = power, Wind = wind, Distance = 5, ObservedLandingX = res.LandingX, ObservedLandingY = 0, ObservedFlightTime = withTime ? res.FlightTime : null });
        }
        return list;
    }

    [Fact]
    public void Evaluate_PerfectModel_HasZeroError()
    {
        var data = SyntheticObservations(Base());
        var eval = _re.Evaluate(Base(), data);
        Assert.All(eval.Predictions, p => Assert.True(p.ErrorDistance < 1e-9));
        Assert.True(eval.Metrics.RootMeanSquareError < 1e-9);
        Assert.True(eval.Metrics.MeanAbsoluteError < 1e-9);
    }

    [Fact]
    public void Metrics_AreComputedCorrectly()
    {
        var p = new List<ExperimentPrediction>
        {
            new() { ErrorX = 3, ErrorDistance = 3 },
            new() { ErrorX = -4, ErrorDistance = 4 },
        };
        var m = ReverseEngineeringService.ComputeMetrics(p);
        Assert.Equal(3.5, m.MeanAbsoluteError, 12);
        Assert.Equal(Math.Sqrt((9 + 16) / 2.0), m.RootMeanSquareError, 12);
        Assert.Equal(4, m.MaxError);
        Assert.Equal(-0.5, m.MeanSignedErrorX, 12);
    }

    [Fact]
    public void ObservedHeightAboveApex_FallsBackToClosestApproach()
    {
        var data = new List<ExperimentData>
        {
            new() { Angle = 45, Power = 20, ObservedLandingX = 1, ObservedLandingY = 50 }
        };
        var eval = _re.Evaluate(Base(), data);
        Assert.False(eval.Predictions[0].ReachedObservedHeight);
        Assert.True(eval.Predictions[0].ErrorDistance > 40);
    }

    [Theory]
    [InlineData(OptimizationMethod.LeastSquares)]
    [InlineData(OptimizationMethod.GridThenLeastSquares)]
    public void Optimizer_RecoversHiddenParameters(OptimizationMethod method)
    {
        var hidden = Base();
        hidden.Calibration.VelocityMultiplier = 1.23;
        hidden.Calibration.GravityMultiplier = 0.81;
        hidden.Calibration.WindMultiplier = 1.7;
        var data = SyntheticObservations(hidden);

        var result = _opt.Optimize(new OptimizationRequest
        {
            Base = Base(),
            Experiments = data,
            Method = method,
            MaxIterations = 200,
            Parameters = new()
            {
                new() { Name = TunableParameter.VelocityMultiplier, Min = 0.5, Max = 2, Steps = 16 },
                new() { Name = TunableParameter.GravityMultiplier, Min = 0.5, Max = 2, Steps = 16 },
                new() { Name = TunableParameter.WindMultiplier, Min = 0, Max = 3, Steps = 7 },
            }
        });

        Assert.True(result.BestMetrics.RootMeanSquareError < 1e-3, $"RMSE {result.BestMetrics.RootMeanSquareError}");
        Assert.True(result.BestMetrics.RootMeanSquareError < result.InitialMetrics.RootMeanSquareError);
        Assert.Equal(1.23, result.BestParameters["VelocityMultiplier"], 2);
        Assert.Equal(0.81, result.BestParameters["GravityMultiplier"], 2);
        Assert.Equal(1.7, result.BestParameters["WindMultiplier"], 1);
    }

    [Fact]
    public void LandingOnly_VelocityAndGravity_AreNotSeparable_ButFitIsStillPerfect()
    {
        // Without flight time, V0 and g only matter through ~V0²/g: many pairs fit equally well.
        var hidden = Base();
        hidden.Calibration.VelocityMultiplier = 1.2;
        hidden.Calibration.GravityMultiplier = 1.2 * 1.2;
        hidden.WindEnabled = false;
        hidden.BarrelLength = 0; hidden.Calibration.LaunchHeight = 0;
        var baseReq = hidden.Clone(); baseReq.Calibration.VelocityMultiplier = 1; baseReq.Calibration.GravityMultiplier = 1;
        var eval = _re.Evaluate(baseReq, SyntheticObservations(hidden, withTime: false));
        Assert.True(eval.Metrics.RootMeanSquareError < 0.01, $"{eval.Metrics.RootMeanSquareError}");
    }

    [Fact]
    public void GridSearch_FindsBestGridPoint()
    {
        var hidden = Base();
        hidden.Calibration.VelocityMultiplier = 1.2; // exactly on the grid
        var data = SyntheticObservations(hidden);

        var result = _opt.Optimize(new OptimizationRequest
        {
            Base = Base(),
            Experiments = data,
            Method = OptimizationMethod.GridSearch,
            Parameters = new() { new() { Name = TunableParameter.VelocityMultiplier, Min = 0.5, Max = 2, Steps = 16 } }
        });

        Assert.Equal(1.2, result.BestParameters["VelocityMultiplier"], 9);
        Assert.True(result.BestMetrics.RootMeanSquareError < 1e-9);
    }

    [Fact]
    public void Solver_SolvesLinearSystem()
    {
        var x = OptimizationService.Solve(new double[,] { { 2, 1 }, { 1, 3 } }, new double[] { 3, 5 });
        Assert.NotNull(x);
        Assert.Equal(0.8, x![0], 12);
        Assert.Equal(1.4, x[1], 12);
        Assert.Null(OptimizationService.Solve(new double[,] { { 1, 2 }, { 2, 4 } }, new double[] { 1, 2 }));
    }
}
